const b = $('Webhook').item.json.body;
const pr = b.pull_request;
const body = pr.body || '';
const agents = ($env.N8N_AGENT_LOGINS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const mentions = (body.match(/@([a-zA-Z0-9-]+)/g) || []).map(m => m.slice(1));
const mentionedLogin = mentions.find(m => agents.includes(m.toLowerCase())) || '';
const args = {
  surface: 'pr-body',
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login,
  senderType: b.sender && b.sender.type,
  prNumber: pr.number,
  prTitle: pr.title,
  prBody: body,
  prUrl: pr.html_url,
  prHeadRef: pr.head && pr.head.ref,
  prBaseRef: pr.base && pr.base.ref,
  prAuthor: pr.user && pr.user.login,
  mentionedLogin,
  title: pr.title,
  bodyText: body,
};
const prompt = `You were @-mentioned by @${args.senderLogin} in the body of PR #${args.prNumber}.
Repo: ${args.repoFull}. Branch: ${args.prHeadRef} \u2192 ${args.prBaseRef}. PR author: @${args.prAuthor}. URL: ${args.prUrl}.

PR title: ${args.prTitle}

PR body:
---
${args.prBody}
---

Reply on the PR thread. For a formal review, redirect the human to request a review (the request-review flow opens a structured review). For an inline code change, redirect them to comment \`@<you> <instruction>\` on a specific file/line. Markdown supported.

Return ONLY the reply body. No preamble.
`;
args.promptB64 = Buffer.from(prompt, 'utf8').toString('base64');
return [{ json: { argsB64: Buffer.from(JSON.stringify(args), 'utf8').toString('base64') } }];
